import React from 'react';
import PropTypes from 'prop-types';
import { connect } from 'react-redux';
import { bindActionCreators } from 'redux';
import { withRouter } from 'react-router-dom';
import { Link } from 'react-router-dom';
import { Form, Input, Button, Message } from 'semantic-ui-react';
import { userLogin } from '../actions/authentication';
import { addFlashMessage } from '../actions/flashMessages';

class LoginForm extends React.Component {
  state = {
    email: '',
    password: '',
    loading: false,
    errors: {}
  };

  isValid = () => {
    const { email, password } = this.state;
    if (!email || !password) {
      this.setState({ errors: { global: 'All fields are required' }, loading: false });
      return false;
    }
    return true;
  };

  handleChange = (event) => {
    this.setState({ ...this.state, [event.target.name]: event.target.value });
  };

  handleSubmit = (event) => {
    event.preventDefault();
    this.setState({ loading: true, errors: {} });
    if (this.isValid()) {
      this.props.userLogin(this.state)
        .then((res) => {
          if (res && res.errors) {
            this.setState({ errors: res.errors, loading: false });
          } else {
            this.props.addFlashMessage({
              type: 'success',
              text: 'You signed in successfully! Welcome back!'
            });
            this.props.history.push('/');
          }
        })
        .catch((err) => {
          this.setState({ errors: { global: err.message }, loading: false });
        });
    }
  };

  render() {
    const { email, password, loading, errors } = this.state;
    return (
      <Form loading={loading} onSubmit={this.handleSubmit} error={!!Object.keys(errors).length}>
        <h2>Login to your account</h2>
        {errors.global && <Message error content={errors.global} />}
        <Form.Field>
          <label htmlFor="email">Email</label>
          <Input
            id="email"
            name="email"
            type="email"
            value={email}
            onChange={this.handleChange}
            placeholder="Enter your email"
          />
        </Form.Field>
        <Form.Field>
          <label htmlFor="password">Password</label>
          <Input
            id="password"
            name="password"
            type="password"
            value={password}
            onChange={this.handleChange}
            placeholder="Enter your password"
          />
        </Form.Field>
        <Button primary type="submit">Login</Button>
        <p>
          Don't have an account? <Link to="/signup">Register</Link>
        </p>
      </Form>
    );
  }
}

LoginForm.propTypes = {
  userLogin: PropTypes.func.isRequired,
  addFlashMessage: PropTypes {
